#!/bin/sh
scan_gpu() { GPU_FAMILY=unknown; GPU_VENDOR=unknown; GPU_MODEL=unknown; GPU_DRIVER=unknown; GPU_NODES=; _d=$(path /dev/dri); if [ -d "$_d" ]; then for _node in "$_d"/*; do [ -c "$_node" ] || continue; GPU_NODES="$GPU_NODES${_node##*/} "; done; fi; _text="$(read_one /sys/firmware/devicetree/base/model) $(read_one /proc/device-tree/model)"; case $_text in *Rockchip*) GPU_FAMILY=mali; GPU_VENDOR=ARM;; *NVIDIA*) GPU_FAMILY=nvidia; GPU_VENDOR=NVIDIA;; *Raspberry*) GPU_FAMILY=videocore; GPU_VENDOR=Broadcom;; esac; [ -n "$GPU_NODES" ] && [ "$GPU_FAMILY" = unknown ] && GPU_FAMILY=other; }
gpu_json() { printf '{"status":"%s","family":' "$( [ "$GPU_FAMILY" = unknown ] && echo unknown || echo detected )"; json_quote "$GPU_FAMILY"; printf ',"vendor":'; json_quote "$GPU_VENDOR"; printf ',"model":'; json_quote "$GPU_MODEL"; printf ',"driver":'; json_quote "$GPU_DRIVER"; printf ',"device_nodes":'; json_quote "$GPU_NODES"; printf ',"compute_compatible":false}'; }
